[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$tmp=Join-Path ([IO.Path]::GetTempPath()) ('spectra-control-negative-'+[guid]::NewGuid().ToString('N'));try{& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\New-SyntheticWorkspaceControlFixture.ps1') -Destination $tmp|Out-Null;$g=Get-Content (Join-Path $tmp 'reference-graph.json') -Raw|ConvertFrom-Json;$g.nodes += 'PRJ-SYNTHETIC-CONTROL';$g|ConvertTo-Json -Depth 8|Set-Content (Join-Path $tmp 'reference-graph.json');& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\Test-SyntheticControlGraph.ps1') -Path $tmp|Out-Null;$duplicate=($LASTEXITCODE -ne 0);if(-not $duplicate){throw 'DUPLICATE_ID_ACCEPTED'};Write-Host 'PASS: Duplicate-ID negative gate.'}finally{if(Test-Path $tmp){Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}}
